class MainActivity : ComponentActivity() {
  private lateinit var jankStats: JankStats

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    // Production jank telemetry — per-frame durations from real devices
    jankStats = JankStats.createAndTrack(window) { frame ->
      if (frame.isJank) {
        Analytics.track("jank", mapOf("ms" to frame.frameDurationUiNanos / 1_000_000))
      }
    }
    PerformanceMetricsState.getHolderForHierarchy(window.decorView)
      .state?.putState("screen", "home")
  }
}

