// proguard-rules.pro — the keep rules themselves
//
//   # Types built by reflection (Gson). kotlinx.serialization needs none:
//   # its compiler plugin generates the serializer, so nothing is looked up by name.
//   -keep class com.app.dto.** { *; }
//
//   # Enum values() / valueOf() are reached reflectively
//   -keepclassmembers enum * {
//     public static **[] values();
//     public static ** valueOf(java.lang.String);
//   }
//
//   # Keep annotations and generic signatures for reflective frameworks
//   -keepattributes *Annotation*,Signature,InnerClasses
//
//   # Native method names must match the JNI symbols
//   -keepclasseswithmembernames class * { native <methods>; }
//
//   # Keep line numbers, then hide the source file name in traces
//   -keepattributes SourceFile,LineNumberTable
//   -renamesourcefileattribute SourceFile

