@RunWith(AndroidJUnit4::class)
class BaselineProfileGenerator {
  @get:Rule val rule = BaselineProfileRule()

  @Test
  fun generate() = rule.collect(
    packageName = "com.example.app",
    includeInStartupProfile = true          // also emits a DEX-layout startup profile
  ) {
    pressHome()
    startActivityAndWait()                  // cold launch
    device.findObject(By.res("feed")).fling(Direction.DOWN)   // the journeys that matter
    device.findObject(By.text("Details")).click()
    device.waitForIdle()
  }
}

// Verify the win instead of assuming it
@RunWith(AndroidJUnit4::class)
class StartupBenchmark {
  @get:Rule val benchmark = MacrobenchmarkRule()

  @Test fun coldStartupNoProfile() = measure(CompilationMode.None())
  @Test fun coldStartupWithProfile() = measure(CompilationMode.Partial())

  private fun measure(mode: CompilationMode) = benchmark.measureRepeated(
    packageName = "com.example.app",
    metrics = listOf(StartupTimingMetric()),
    iterations = 10,
    startupMode = StartupMode.COLD,
    compilationMode = mode
  ) {
    pressHome()
    startActivityAndWait()
  }
}

