// App Startup — one ContentProvider for every library initializer, in a declared order
class AnalyticsInitializer : Initializer<AnalyticsClient> {
  override fun create(context: Context): AnalyticsClient =
    AnalyticsClient.init(context).also { it.start() }

  override fun dependencies(): List<Class<out Initializer<*>>> = emptyList()
}

// Defer non-critical work until the main thread is idle, after the first frame
class MyApp : Application() {
  override fun onCreate() {
    super.onCreate()
    Looper.myQueue().addIdleHandler {
      AnalyticsClient.init(this).start()
      ImageLoader.warmup()
      false                                     // run once
    }
  }
}

// Splash: hold it only while data the first screen cannot render without is missing
class MainActivity : ComponentActivity() {
  override fun onCreate(savedInstanceState: Bundle?) {
    val splash = installSplashScreen()
    splash.setKeepOnScreenCondition { vm.state.value.isBootstrapping }
    super.onCreate(savedInstanceState)
    setContent {
      val state by vm.state.collectAsStateWithLifecycle()
      HomeScreen(state)
      if (!state.isLoading) ReportDrawn()        // marks time-to-full-display
    }
  }
}

